const pill=(text,type='')=>`<span class="pill ${type}">${e(text)}</span>`;
const sectionHead=(title,action='',extra='')=>`<div class="section-head"><h2>${e(t(title))}${extra}</h2>${action}</div>`;
const jump=(target,label='viewAll')=>`<button type="button" data-page="${target}">${e(t(label))}${ico('arrow')}</button>`;
const stat=(label,value,icon,type='',hint='')=>`<article class="stat"><span class="stat-icon ${type}">${ico(icon)}</span><span class="stat-label">${e(t(label))}</span><strong>${num(value)}</strong>${hint?`<small>${e(hint)}</small>`:''}</article>`;
function attendanceStatus(row){if(row.absence)return {text:t('agreedAbsence'),type:'blue'};const s=row.status;if(s==='На смене')return {text:t('onShift'),type:'green'};if(s==='Перерыв')return {text:t('onBreak'),type:'orange'};if(s==='Не закрыта')return {text:t('notClosed'),type:'orange'};if(s==='Нет отметки'||!row.arrival)return {text:t('noMark'),type:''};if(row.lateMinutes>0)return {text:t('lateMinutes')+' '+num(row.lateMinutes)+' '+t('minute'),type:'orange'};return {text:row.departure?t('closed'):String(s||t('noMark')),type:row.departure?'blue':''}}
const stageLabel=s=>t(({screening:'review',shortlist:'review',contacted:'review',new:'new',review:'review',interview:'interview',offer:'offer',hired:'hired',rejected:'rejected',withdrawn:'withdrawn',scheduled:'scheduled',confirmed:'confirmed',cancelled:'cancelled',completed:'completed',done:'done',open:'open'}[s])||s||'new');
function reportButton(person){return view?.capabilities?.reports?.read&&window.AttendanceExport?window.AttendanceExport.button(person?.id||'',person?.name||'',language):''}
function staffRow(person){const row=view.attendance?.rows.find(x=>x.employee===person.id),s=row?attendanceStatus(row):{text:person.active?t('active'):t('archive'),type:person.active?'blue':''};return `<div class="manager-report-row"><button class="person-row" type="button" data-employee="${e(person.id)}" aria-label="${e(person.name)}"><span class="person-avatar">${e(initials(person.name))}</span><span class="person-details"><strong>${e(person.name)}</strong><small>${e(person.role)}</small></span><span class="person-side">${row?.arrival?`<span class="time">${time(row.arrival)}</span>`:''}${pill(s.text,s.type)}</span></button>${reportButton(person)}</div>`}
function attendanceRow(row){const s=attendanceStatus(row),employee=view.staff.find(x=>x.id===row.employee),proof=videoEvidence(row);return `<div class="attendance-row-with-proof"><${employee?'button':'div'} class="person-row"${employee?` type="button" data-employee="${e(row.employee)}"`:''}><span class="person-avatar">${e(initials(row.name))}</span><span class="person-details"><strong>${e(row.name)}</strong><small>${e(row.role)}</small>${row.lateMinutes>0?`<span class="row-late">${e(t('lateMinutes'))}: ${num(row.lateMinutes)} ${e(t('minute'))}</span>`:''}</span><span class="person-side"><span class="time">${time(row.arrival)}${row.departure?' · '+time(row.departure):''}</span>${pill(s.text,s.type)}</span></${employee?'button':'div'}>${proof?`<button type="button" class="proof-button" data-video-proof="${e(row.employee)}" aria-label="${e(t('videoMark'))}: ${e(row.name)}">${ico('camera')}</button>`:''}</div>`}
function taskRows(rows){return rows.map(q=>{const overdue=q.overdue===true||q.status==='overdue';return `<article class="task"><span class="task-icon ${overdue?'red':'blue'}">${ico(overdue?'alert':q.kind==='candidate'?'team':q.kind==='document'?'file':'clock')}</span><div class="task-copy"><strong>${e(q.title||q.name||q.action||t('dayTasks'))}</strong><p>${e(q.person||q.employeeName||q.name||q.description||q.detail||q.sourceTitle||'')}</p><div class="meta">${q.due?pill(t('due')+': '+date(q.due),overdue?'red':''):''}${q.ownerName||q.owner?`<small class="muted">${e(q.ownerName||q.owner)}</small>`:''}</div></div><a class="task-link" href="/#hrcenter" aria-label="${e(t('viewInWeb'))}">${ico('arrow')}</a></article>`}).join('')}
const candidateRows=rows=>rows.map(c=>`<button class="person-row" type="button" data-candidate="${e(c.id)}"><span class="person-avatar">${e(initials(c.name))}</span><span class="person-details"><strong>${e(c.name)}</strong><small>${e(c.role||t('vacancy'))}</small></span><span class="person-side">${pill(stageLabel(c.stage),c.stage==='hired'?'green':c.stage==='rejected'?'':'blue')}</span></button>`).join('');
const interviewRows=rows=>rows.map(i=>`<button class="person-row" type="button" data-interview="${e(i.id)}"><span class="calendar-date">${time(i.start)}<small>${date(i.start)}</small></span><span class="person-details"><strong>${e(i.name||i.candidateName||t('interview'))}</strong><small>${e(i.place||'')} · ${num(i.duration)} ${e(t('minute'))}</small></span><span class="person-side">${pill(stageLabel(i.status),i.status==='confirmed'?'green':i.status==='cancelled'?'':'blue')}</span></button>`).join('');
