function availableLink(key){return view.links?.find(x=>x.key===key)}
function has(key){return !!view.capabilities?.[key]?.read}
function quickLink(key,label,hint,icon){const item=availableLink(key);if(!item)return '';return `<a class="quick" href="${e(safeHref(item.href))}">${ico(icon)}<span>${e(t(label))}</span>${hint?`<small>${e(t(hint))}</small>`:''}</a>`}
function period(type,calendar=false){const compact=type==='day'&&!calendar&&page==='overview';return `<div class="period ${compact?'overview-date':''}">${compact?'':ico('calendar')}<label>${compact?`<span class="period-display">${e(longDate(day))}</span>`:e(t(calendar?'meetingDate':type))}<input id="manager-period" type="${type==='month'?'month':'date'}" value="${e(type==='month'?month:day)}"${type==='day'&&!calendar&&view?.today?` max="${e(view.today)}"`:''} aria-label="${e(t(calendar?'meetingDate':type))}"></label>${compact?'':`<span class="sync-label">${view?.generated?e(t('updated'))+' '+time(view.generated):''}</span>`}</div>`}
function filteredInterviews(){return (view.hr?.interviews||[]).filter(x=>interviewAllDates||String(x.localStart||'').startsWith(day)||(!x.localStart&&new Intl.DateTimeFormat('en-CA',{timeZone:view.timezone||'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(x.start))===day))}
function localizedNotice(n){if(language!=='uz')return n;const count=num(n.params?.count),m=String(n.params?.month||month||'');const labels={'missing-marks':['Kelish belgilari yo‘q',`${count} xodimda kelish belgisi yo‘q. Belgining yo‘qligi xodimning yo‘qligini isbotlamaydi.`],'unclosed-shifts':['Yopilmagan smenalar',`${count} ta smena yopilmagan. Vaqt belgilarini tekshiring.`],'hr-overdue':['HR vazifalari muddati o‘tgan',`${count} ta HR vazifasi muddati o‘tgan. Mas’ul bilan muddatni tekshiring.`],'new-applications':['Yangi arizalar',`${count} ta yangi nomzod arizasi ko‘rib chiqishni kutmoqda.`],'expiring-documents':['Hujjatlar muddatini tekshiring',`${count} ta hujjatning muddati yaqinlashgan yoki o‘tgan.`],'training-overdue':['Ta’lim muddati o‘tgan',`${count} ta o‘quv kursi belgilangan muddatda tugallanmagan.`],'missing-payroll':['Hisob-kitoblar yaratilmagan',`${count} xodim uchun ${m} oyida hisob-kitob yaratilmagan.`],'offline-cameras':['Kameralar bilan aloqa yo‘q',`${count} ta kameradan kadr olinmagan. Ulanishni tekshiring.`]};const pair=labels[n.code];return pair?{...n,title:pair[0],text:pair[1]}:n}

